import tgpu from 'typegpu';

export const LightUniform = tgpu.struct({
  color: tgpu.vec3f,
  intensity: { type: tgpu.f32, size: 16 },
  direction: tgpu.vec3f,
  castsShadow: { type: tgpu.u32, align: 16 },
});

export const lightUniformSize: number = tgpu.structSize(LightUniform);
